if($search!==''){$filter='WHERE l.nom_laboratoire LIKE ? OR l.ville LIKE ?';$params=['%'.$search.'%','%'.$search.'%'];}
$q=$pdo->prepare("SELECT i.`$imageId` id,i.`$imagePath` chemin,$imageDate created_at,l.`$labId` laboratoire_id,l.nom_laboratoire,l.ville FROM image_laboratoire i JOIN laboratoire l ON l.`$labId`=i.laboratoire_id $filter ORDER BY $imageSort i.`$imageId` DESC");$q->execute($params);$images=$q->fetchAll();
